Hello,

 I was a WinBUGS user a couple of years ago, and now I'm back in Bayesian statistics. I'm a newbie in Stan.

In order to train myself, I have programmed the model in Tunaru's paper " <http://www.statistik.tuwien.ac.at/oezstat/ausg022-3/papers/tunaru.pdf>Hierarchical Bayesian Models for Multiple Count Data" <http://www.statistik.tuwien.ac.at/oezstat/ausg022-3/papers/tunaru.pdf>.  There's a slight difference in my model as compared to the original model given in the paper: I add a known parameter S_{k,i} in the mean of the Poisson distributions (S_{k,i}=1 in the paper and in my code the indices are S_{i,j}). This is not important.

Firstly I simulate some data and I fit the model with JAGS:

###########################
### simulations of data ###
###########################
library(mvtnorm)
set.seed(666)
N <- 50
M <- 3
Sigma0 <- rWishart(1, df=M+1, diag(M))[,,1]/5
S <- matrix(100, nrow=N, ncol=M)
Mu <- rep(0,M)
Lambda <-  exp(rmvnorm(N, Mu, Sigma0))
Y <- matrix(rpois(N*M, Lambda*S), nrow=N)
colnames(Y) <- paste0("y", 1:M)

###########################
###     JAGS model      ###
###########################
library(rjags)
# write the model #
model.file <- "Tunaru.jags"
wb.model <- function(){
  # data
  for(i in 1:N){
    logLambda[i,1:M] ~ dmnorm(Mu[1:M], invSigma[1:M,1:M])
    for(j in 1:M){
      lambda[i,j] <- exp(logLambda[i,j])*S[i,j]
      Y[i,j] ~ dpois(lambda[i,j])
    }
  }
  # priors
  invSigma[1:M,1:M] ~ dwish(invSigma0[1:M,1:M], nu0)
  for(j in 1:M){
    Mu[j] ~ dnorm(0, 0.000001)
  }
  #
  Sigma[1:M,1:M] <- inverse(invSigma[,])
}
R2WinBUGS::write.model(wb.model, model.file) # write model file

# set data and initial values #
dat <- list(N=N,
            M=M,
            Y=Y,
            S=S,
            invSigma0=diag(M)/1000,
            nu0=M)
inits <- function(){
  logLambda <- log(Y/S+.1)
  list(
    logLambda = logLambda + rnorm(1,0,1),
    invSigma = solve(var(logLambda + rnorm(1,0,1))),
    Mu = colMeans(logLambda) + rnorm(1,0,1)
  )
}

# run warm-up #
jags <- jags.model(model.file,
                   data = dat,
                   inits=inits,
                   n.chains = 4,
                   n.adapt = 10000)

# update #
parameters <- c("Mu", "Sigma")
samples_jags <- samples <- coda.samples(jags,
                                        parameters,
                                        10000)

# summary #
summary(samples)

